{
    if (m_isDetachedFromDali)
        throw MakeStringException(-1, "Cannot list ESDL Bindings. ESP is currently detached from DALI.");

    double ver = context.getClientVersion();
    Owned<IPropertyTree> esdlBindings = m_esdlStore->getBindings();
    IArrayOf<IEspESDLBinding> list;
    if (esdlBindings.get() != nullptr)
    {
        Owned<IPropertyTreeIterator> iter = esdlBindings->getElements("Binding");
        ForEach(*iter)
        {
            IPropertyTree &item = iter->query();
            Owned<IEspESDLBinding> esdlbinding = createESDLBinding("","");
            esdlbinding->setId(item.queryProp("@id"));
            esdlbinding->setEspProcess(item.queryProp("@espprocess"));
            const char* portstr = item.queryProp("@port");
            if (portstr && *portstr)
                esdlbinding->setPort(atoi(portstr));
            else
                esdlbinding->setPort(0);
            esdlbinding->setEspBinding(item.queryProp("@espbinding"));

            if( ver >= 1.4)
            {
                IEspPublishHistory& bindhistory = esdlbinding->updateHistory();
                addPublishHistory(&item, bindhistory);
            }
            list.append(*esdlbinding.getClear());
        }
        list.sort(bindingCompareFunc);
    }

    if (ver >= 1.4)
    {
        StringArray allProcNamesSorted;
        getAllEspProcessesSorted(allProcNamesSorted);
        unsigned procNameInd = 0;
        IArrayOf<IConstEspProcessStruct>& processes = resp.getEspProcesses();
        IConstESDLBinding* lastBinding = nullptr;
        Owned<IEspEspProcessStruct> currentProcess = nullptr;
        Owned<IEspEspPortStruct> currentPort = nullptr;
        for (int i = 0; i < list.length(); i++)
        {
            IConstESDLBinding* binding = &list.item(i);
            bool processCreated = false;
            if (!lastBinding || (strcmp(lastBinding->getEspProcess(), binding->getEspProcess()) != 0))
            {
                const char* curProc = binding->getEspProcess();

                //Include empty ESP processes that are alphabetically smaller than current non-empty process
                for ( ; procNameInd < allProcNamesSorted.length() && strcmp(allProcNamesSorted.item(procNameInd), curProc) < 0; procNameInd++)
                {
                    currentProcess.setown(createEspProcessStruct());
                    currentProcess->setName(allProcNamesSorted.item(procNameInd));
                    processes.append(*currentProcess.getLink());
                }

                if (procNameInd < allProcNamesSorted.length() && streq(allProcNamesSorted.item(procNameInd), curProc))
                {
                    procNameInd++;
                }

                currentProcess.setown(createEspProcessStruct());
                currentProcess->setName(curProc);
                processes.append(*currentProcess.getLink());
                processCreated = true;
            }

            if (processCreated || lastBinding->getPort() != binding->getPort())
            {
                IArrayOf<IConstEspPortStruct>& ports = currentProcess->getPorts();
                currentPort.setown(createEspPortStruct());
                currentPort->setValue(binding->getPort());
                ports.append(*currentPort.getLink());
            }

            IArrayOf<IConstESDLBinding>& bindings = currentPort->getBindings();
            bindings.append(*LINK(binding));
            lastBinding = binding;
        }

        //Include remaining empty ESP processes
        for ( ; procNameInd < allProcNamesSorted.length(); procNameInd++)
        {
            currentProcess.setown(createEspProcessStruct());
            currentProcess->setName(allProcNamesSorted.item(procNameInd));
            processes.append(*currentProcess.getLink());
        }
    }
    else
        resp.setBindings(list);
    return true;
}

{
    context.ensureFeatureAccess(FILE_IO_URL, SecAccess_Write, ECLWATCH_ACCESS_TO_FILE_DENIED, "WsFileIO::CreateFile: Permission denied");

    StringBuffer result;
    const char* server = req.getDestDropZone();
    if (!server || (server[0] == 0))
    {
        resp.setResult("Destination not specified");
        return true;
    }

    const char* destRelativePath = req.getDestRelativePath();
    if (!destRelativePath || (destRelativePath[0] == 0))
    {
        resp.setResult("Destination path not specified");
        return true;
    }

    resp.setDestDropZone(server);
    resp.setDestRelativePath(destRelativePath);

    CDfsLogicalFileName dlfn;
    validateDropZoneAccess(context, server, req.getDestNetAddress(), SecAccess_Write, destRelativePath, dlfn);

    RemoteFilename rfn;
    dlfn.getExternalFilename(rfn);
    Owned<IFile> file = createIFile(rfn);

    fileBool isDir = file->isDirectory();
    if (isDir == fileBool::foundYes)
    {
        result.appendf("Failure: %s is a directory.", destRelativePath);
        resp.setResult(result.str());
        return true;
    }

    if (!req.getOverwrite() && (isDir != fileBool::notFound))
    {
        result.appendf("Failure: %s exists.", destRelativePath);
        resp.setResult(result.str());
        return true;
    }

    file->open(IFOcreate);
    result.appendf("%s has been created.", destRelativePath);
    resp.setResult(result.str());
    return true;
}

{
    context.ensureFeatureAccess(FILE_IO_URL, SecAccess_Read, ECLWATCH_ACCESS_TO_FILE_DENIED, "WsFileIO::ReadFileData: Permission denied");

    StringBuffer result;
    const char* server = req.getDestDropZone();
    if (!server || (server[0] == 0))
    {
        resp.setResult("Destination not specified");
        return true;
    }

    //Despite the "DestRelativePath" saying it's relative for legacy reason, it also supports absolute paths.
    const char* destRelativePath = req.getDestRelativePath();
    if (!destRelativePath || (destRelativePath[0] == 0))
    {
        resp.setResult("Destination path not specified");
        return true;
    }

    resp.setDestDropZone(server);
    resp.setDestRelativePath(destRelativePath);

    __int64 dataSize = req.getDataSize();
    __int64 offset = req.getOffset();
    resp.setDataSize(dataSize);
    resp.setOffset(offset);
    if (dataSize < 1)
    {
        resp.setResult("Invalid data size.");
        return true;
    }

    if (offset < 0)
    {
        resp.setResult("Invalid offset.");
        return true;
    }

    CDfsLogicalFileName dlfn;
    validateDropZoneAccess(context, server, req.getDestNetAddress(), SecAccess_Read, destRelativePath, dlfn);

    StringBuffer user;
    RemoteFilename rfn;
    dlfn.getExternalFilename(rfn);
    Owned<IFile> file = createIFile(rfn);
    fileBool isFile = file->isFile();
    if (isFile != fileBool::foundYes)
    {
        result.appendf("%s does not exist.", destRelativePath);
        resp.setResult(result.str());
        return true;
    }

    Owned<IFileIO> io = file->open(IFOread);
    __int64 size = io->size();
    if (offset >= size)
    {
        result.appendf("Invalid offset: file size = %" I64F "d.", size);
        resp.setResult(result.str());
        return true;
    }

    __int64 dataToRead = size - offset;
    if (dataToRead > dataSize)
    {
        dataToRead = dataSize;
    }

    MemoryBuffer membuf;
    char* buf = (char*) membuf.reserve((int) dataToRead);
    if (io->read(offset, (int)dataToRead, buf) != dataToRead)
    {
        resp.setResult("ReadFileData error.");
        LOG(MCprogress, "ReadFileData error: %s: %s %s", context.getUserID(user).str(), server, destRelativePath);
    }
    else
    {
        resp.setData(membuf);
        resp.setResult("ReadFileData done.");
        LOG(MCprogress, "ReadFileData done: %s: %s %s", context.getUserID(user).str(), server, destRelativePath);
    }

    return true;
}

{
    context.ensureFeatureAccess(FILE_IO_URL, SecAccess_Write, ECLWATCH_ACCESS_TO_FILE_DENIED, "WsFileIO::WriteFileData: Permission denied");

    StringBuffer result;
    const char* server = req.getDestDropZone();
    if (!server || (server[0] == 0))
    {
        resp.setResult("Destination not specified");
        return true;
    }

    const char* destRelativePath = req.getDestRelativePath();
    if (!destRelativePath || (destRelativePath[0] == 0))
    {
        resp.setResult("Destination path not specified");
        return true;
    }

    MemoryBuffer& srcdata = (MemoryBuffer&)req.getData();
    if(srcdata.length() == 0)
    {
        resp.setResult("Source data not specified");
        return true;
    }

    __int64 offset = req.getOffset();
    bool append = req.getAppend();  
    if (append)
    {
        resp.setAppend(true);
    }
    else
    {
        resp.setOffset(offset);
    }

    resp.setDestDropZone(server);
    resp.setDestRelativePath(destRelativePath);

    CDfsLogicalFileName dlfn;
    validateDropZoneAccess(context, server, req.getDestNetAddress(), SecAccess_Write, destRelativePath, dlfn);

    StringBuffer user;
    RemoteFilename rfn;
    dlfn.getExternalFilename(rfn);
    Owned<IFile> file = createIFile(rfn);
    fileBool isFile = file->isFile();
    if (isFile != fileBool::foundYes)
    {
        result.appendf("%s does not exist.", destRelativePath);
        resp.setResult(result.str());
        return true;
    }

    if (append)
    {
        Owned<IFileIO> io = file->open(IFOread);
        offset = io->size();
    }

    Owned<IFileIO> fileio = file->open(IFOwrite);
    size32_t len = srcdata.length();
    if (fileio->write(offset, len, srcdata.readDirect(len)) != len)
    {
        resp.setResult("WriteFileData error.");
        LOG(MCprogress, "WriteFileData error: %s: %s %s", context.getUserID(user).str(), server, destRelativePath);
    }
    else
    {
        resp.setResult("WriteFileData done.");
        LOG(MCprogress, "WriteFileData done: %s: %s %s", context.getUserID(user).str(), server, destRelativePath);
    }

    return true;
}

